"""Small owned fixture; never imported by the scenario loader."""


def normalize_status(status: str | None) -> str:
    return status.lower()

import unittest
from orders import normalize_status

class NullHandling(unittest.TestCase):
    def test_null(self) -> None:
        self.assertEqual(normalize_status(None), "pending")
    def test_normal(self) -> None:
        self.assertEqual(normalize_status("PAID"), "paid")
